from pathlib import Path
import subprocess,json,shutil
p=Path(__file__).resolve().parents[1]; root=p.parents[2]
rows=[
('kujo','VM-first bytecode runtime, compiler and CLI','1.9.0 release documented','src/vm.rs; src/compiler.rs; docs/RELEASE_NOTES_1_9_0.md','No complete language safety or live-provider certification claim.'),
('dispatch','Persisted workflow state, approval gates, retries and recovery','1.4.1 release documented','src; docs/RELEASE_1_4_1.md','Trusted local host; effect assurance beta and participant interoperability alpha are experimental.'),
('workcell','Disposable Git workspace, Docker/Podman resource bounds, declared exports, receipt verification','1.3.0 stable local contract documented','src; docs/compatibility.md','Requires pinned runtime and supported host; no compromised-host protection. Remote adapters alpha, not certified here.'),
('eval','Deterministic checks and machine-readable evaluation results','source inspected; local demo separately verified','main.kujo; src; examples/agent_output.json','Only configured checks; no proof of semantic correctness or independent attestation.'),
('spec','Task contracts and acceptance criteria','1.0.2 release documented','src; README.md','A contract does not enforce all runtime boundaries.'),
('runledger','Local JSON run receipts, supplied commands/results and Git facts','1.2.1 release documented','runledger.kujo; README.md','Does not execute or independently prove recorded tests.'),
('shipcheck','Explicit release-readiness scans and CI gates','1.0.2 production-forward alpha','shipcheck.kujo; README.md','Not release certification; a human decides to ship.'),
('casefile','Capture executed command output and exit code into debugging bundles','1.0.2 documented; demo locally verified','casefile.kujo; FLAGS.md','Trusted local host, bounded/redacted logs; successful capture can contain failed command.'),
('watchdog','OpenAI-compatible proxy and local telemetry database/dashboard','1.2.2 release documented','README.md; docs/DEPLOYMENT_HARDENING_RUNBOOK.md','Estimated costs are not invoices. Authentication/TLS/retention are deployment responsibilities.'),
('kennel','Kujo package manifests, resolution and installation','source inspected','src/resolver.kujo; src/installer.kujo','Package distribution is not adoption evidence.'),
('mcp','Kujo MCP server framework and guarded repo scaffolding','1.3.3 release documented','src; README.md','Remote deployments need ingress/auth/capacity review; not blanket agent integration.'),
('packwrite','Compiles prompt/context into validated agent execution packs','1.1.1 installed','src/ai.kujo; src/pack.kujo; src/validate.kujo','Does not implement the project. Provider availability depends on credentials/model.'),
('kujo-workflows','Portable bounded execution/evaluation workflow harness','source inspected; task gates run locally','loop-engineering/scripts/run-workflow.sh','Bash harness records/gates actions; editorial judgment is performed by this assistant, not a built-in investor judge.'),
('presentations','Kujo SSG/SiteKit static deck rendering, notes console, print/read editions','0.3.1 preview; built locally','src/render.kujo; docs/presentation-features.md','Preview APIs may change; fixed 16:9 canvas needs reading edition on small screens.')]
claims=[]
for i,(repo,cap,status,files,limits) in enumerate(rows,1):
 d=root/repo; commit=subprocess.check_output(['git','-C',str(d),'rev-parse','HEAD'],text=True).strip(); readme=(d/'README.md').read_text(); (p/'research'/f'{repo}-README.md').write_text(readme)
 claims.append(dict(id=f'T{i:02}',project=repo,capability=cap,status=status,source=f'https://github.com/kujolang/{repo}/blob/{commit}/README.md',commit=commit,files=files,limitations=limits,accessed='2026-11-09',confidence='High for documented scope; local verification only where stated'))
(p/'research/capabilities.json').write_text(json.dumps(claims,indent=2))
external=[('M01','84% of respondents use or plan to use AI development tools; 46% distrust output accuracy','https://survey.stackoverflow.co/2025/ai','2025 survey','Self-selected survey; different question denominators (33,662 usage; 33,244 trust). Neither statistic measures autonomous production deployment.'),('M02','52% do not use agents or use simpler tools','https://survey.stackoverflow.co/2025/ai','2025 survey','Agent question includes work beyond development; 31,877 responses. Do not imply remaining respondents all run production agents.'),('C01','Copilot offers agentic tasks, code review and session continuity','https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-on-github','2026-10-28 availability noted','Strong incumbent distribution and existing review controls. No superiority benchmark.'),('C02','LangGraph checkpoints support interruption/recovery and human review','https://docs.langchain.com/oss/python/langgraph/persistence','Undated living documentation','Application-specific persistence and idempotency remain important; not a complete release approval system by itself.'),('F01','Robert DeVore describes years of WordPress/WooCommerce work and current Kujo infrastructure','https://robertdevore.com/about/','Undated first-person biography','Self-reported; no invented employers, tenure counts, employees, advisors, or security credentials. Ecosystem output may include collaborators and AI assistance.'),('P01','Financing, commercial model, December 2026 campaign and customer targets','MEGA_PROMPT.md','2026-11-09 assignment','User-provided scenario / analyst assumptions. No agreed financing, validated valuation or customer interviews.')]
text='# Claims and evidence register\n\nResearch cut: 2026-11-09. Release labels refer to repository documentation, not an assertion that every HEAD feature shipped. Pinned README snapshots are retained for review. No commercial traction evidence supplied.\n\n'
for c in claims:text+=f'## {c["id"]} — {c["project"]}\n- Claim: {c["capability"]}\n- Maturity: {c["status"]}\n- Source: {c["source"]}\n- Supporting paths: {c["files"]}\n- Accessed: {c["accessed"]}; commit: {c["commit"]}\n- Confidence: {c["confidence"]}\n- Limitations: {c["limitations"]}\n\n'
for id,claim,url,date,limit in external:text+=f'## {id}\n- Claim: {claim}\n- Source: {url}\n- Published: {date}; accessed 2026-11-09\n- Confidence: High for cited text; Medium for generalization; assumptions unvalidated.\n- Limitations: {limit}\n\n'
text+='## Discovery and brand\nInspected official website via HTTP (web reader failed twice), docs root, GitHub org, releases, tooling, showcases (HTTP fallback), and workflows collection. Docs release inventory is dated 2026-10-22; local repositories can be newer. SiteKit source uses #060606, #ffffff, gray surfaces, monospace typography and Departure Mono. Original official kujo-logomark.svg and Departure Mono copied unchanged from website checkout. No invented brand accent.\n\n## Evidence relationship\nCaseFile runs and captures the command; Eval evaluates configured conditions; RunLedger stores user-supplied outcomes. This deck demonstrates CaseFile plus Eval via an explicit local script, not a universal turnkey integration, cryptographic attestation, Workcell isolation, or production agent deployment. Benchmark is a correctness fixture, not a speed or competitor benchmark.\n'
(p/'research/CLAIMS.md').write_text(text)
for f in ['kujo-logomark.svg']:shutil.copy(root/'kujolang.ai-work/assets/images'/f,p/'assets'/f)
shutil.copy(root/'kujolang.ai-work/assets/css/fonts/DepartureMono-Regular.woff2',p/'assets/DepartureMono-Regular.woff2')
(p/'research/BRAND.md').write_text('Official website inspected 2026-11-09. Sources: https://kujolang.ai and local kujolang.ai-work/assets/css/{sitekit.css,style.css}. Monochrome, square geometry, fine rules, Departure Mono headlines and labels. Deck preserves mark proportions and uses system sans for dense evidence, with restrained monospace headlines. No decorative photos. Architecture and lifecycle are editable HTML. Font provenance: website bundled Departure Mono; retain upstream font license.\n')
